contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val1, uint val2) public payable {
        require(val1 != val2);

        uint m0 = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val1); if (__ESBMC_reverted()) return;
        uint m1 = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val2); if (__ESBMC_reverted()) return;
        uint m2 = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(val1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(m1 == val1 && m2 == val2 && m2 != m1 && reverted && c.MinSum() == val2);
    }

    receive() external payable {}
}

